module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg, addb_reg;
reg [DATA_WIDTH:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        sum <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
            sum <= {1'b0, adda} + {1'b0, addb};
            o_en <= 1;
        end else begin
            o_en <= 0;
        end
    end
end

assign result = sum;

endmodule
